/**
 * Formex part roots wrapped as the content service assembles a multi-part act:
 * each part's prolog stripped, the roots inside one `<formex-multipart>`.
 */
function formexMultipart(parts: readonly string[]): string {
  return [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<!-- Assembled by eur-lex-mcp-server from multi-part Formex 4 streams (CELLAR returned HTTP 300 Multiple Choices). Each child is one part root, in stream order. -->',
    `<formex-multipart parts="${parts.length}">`,
    ...parts,
    '</formex-multipart>',
  ].join('\n');
}

